Use `static` data members shared by all objects. The constructor increments the created count and active count; the destructor increments the destroyed count and decrements the active count.

```cpp
#include <iostream>
using namespace std;

class Counter {
    static int created, destroyed, active;
public:
    Counter()  { created++;   active++;  }
    Counter(const Counter &) { created++; active++; }   // copies are objects too
    ~Counter() { destroyed++; active--;  }
    static void show() {
        cout << "Created: " << created
             << "  Destroyed: " << destroyed
             << "  Active: " << active << endl;
    }
};
int Counter::created = 0;
int Counter::destroyed = 0;
int Counter::active = 0;

int main() {
    Counter a, b;
    Counter::show();            // Created: 2  Destroyed: 0  Active: 2
    {
        Counter c, d, e;
        Counter::show();        // Created: 5  Destroyed: 0  Active: 5
    }                           // c, d, e destroyed here
    Counter::show();            // Created: 5  Destroyed: 3  Active: 2
    Counter *p = new Counter;
    Counter::show();            // Created: 6  Destroyed: 3  Active: 3
    delete p;
    Counter::show();            // Created: 6  Destroyed: 4  Active: 2
    return 0;
}
```

