Multilevel inheritance: `student` -> `test` -> `result`. `result` indirectly gets roll number (from `student`) and marks (from `test`).

```cpp
#include <iostream>
using namespace std;

class student {
protected:
    int roll_number;
public:
    void get_roll(int r) { roll_number = r; }
    void put_roll() { cout << "Roll Number : " << roll_number << endl; }
};

class test : public student {
protected:
    float sub1, sub2;
public:
    void get_marks(float m1, float m2) { sub1 = m1; sub2 = m2; }
    void put_marks() {
        cout << "Marks in Subject 1 : " << sub1 << endl;
        cout << "Marks in Subject 2 : " << sub2 << endl;
    }
};

class result : public test {
    float total;
public:
    void display() {
        total = sub1 + sub2;
        put_roll();
        put_marks();
        cout << "Total Marks : " << total << endl;
    }
};

int main() {
    result r;
    r.get_roll(101);
    r.get_marks(78, 85);
    r.display();
    return 0;
}
```

Output:
```
Roll Number : 101
Marks in Subject 1 : 78
Marks in Subject 2 : 85
Total Marks : 163
```

This is a conversion from one class type to another. It is done with a conversion operator (or a constructor) in one of the classes. Here a conversion operator `operator minutes()` is defined in class `time`.

```cpp
#include <iostream>
using namespace std;

class minutes {
    int totalminutes;
public:
    minutes(int m = 0) : totalminutes(m) {}
    void show() { cout << "Total minutes = " << totalminutes << endl; }
};

class time {
    int hrs, mins;
public:
    time(int h = 0, int m = 0) : hrs(h), mins(m) {}
    operator minutes() {                       // time -> minutes
        return minutes(hrs * 60 + mins);
    }
    void show() { cout << hrs << " hrs " << mins << " mins" << endl; }
};

int main() {
    time t(2, 30);
    t.show();
    minutes m = t;          // implicit conversion calls operator minutes()
    m.show();
    return 0;
}
```

Output:
```
2 hrs 30 mins
Total minutes = 150
```

Formula: $totalminutes = hrs \times 60 + mins$. (If the name `time` clashes with `<ctime>`, rename the class, e.g. `Time`.)

```cpp
#include <iostream>
using namespace std;

class Time {
    int hours, minutes, seconds;
public:
    Time() : hours(0), minutes(0), seconds(0) {}                       // no-argument constructor
    Time(int h, int m, int s) : hours(h), minutes(m), seconds(s) {}    // three-argument constructor

    void display() const {                                             // hh:mm:ss format
        cout << hours << ":" << minutes << ":" << seconds << endl;
    }

    void add(Time t1, Time t2) {                                       // adds two Time objects
        seconds = t1.seconds + t2.seconds;
        minutes = t1.minutes + t2.minutes + seconds / 60;
        seconds = seconds % 60;
        hours   = t1.hours + t2.hours + minutes / 60;
        minutes = minutes % 60;
    }
};

int main() {
    Time t1(10, 52, 37), t2(2, 20, 45), t3;     // t3 not initialised (zeros)
    t3.add(t1, t2);
    cout << "Sum = ";
    t3.display();
    return 0;
}
```

Output:
```
Sum = 13:13:22
```

Working: seconds $37+45 = 82 \Rightarrow 22$ s, carry 1 min; minutes $52+20+1 = 73 \Rightarrow 13$ min, carry 1 hr; hours $10+2+1 = 13$.

**(i) Pointer to member**

A pointer to member holds the address (offset) of a class member rather than of an object's member. It is declared using the scope operator: `type class_name::*ptr_name`. It must be used with an object through `.*` (object) or `->*` (pointer to object). The address is obtained with `&class_name::member`.

```cpp
#include <iostream>
using namespace std;

class A {
public:
    int x;
    void show(int v) { cout << "Value = " << v << endl; }
};

int main() {
    int A::*px = &A::x;                  // pointer to data member
    void (A::*pf)(int) = &A::show;       // pointer to member function

    A obj;  A *p = &obj;
    obj.*px = 10;                        // obj.x = 10
    cout << p->*px << endl;              // 10
    (obj.*pf)(obj.x);                    // calls obj.show(10)
    (p->*pf)(20);                        // calls show(20)
}
```

Note: this is different from `&obj.x`, which is an ordinary pointer to that object's member.

**(ii) Static data members and member functions**

- A **static data member** is shared by all objects of the class; only one copy exists. It is declared with `static` inside the class and must be defined (and optionally initialised) outside it. It is zero initialised by default.
- A **static member function** can access only static members of the class, has no `this` pointer, and can be called without an object using `ClassName::function()`.

```cpp
#include <iostream>
using namespace std;

class Item {
    static int count;          // shared by all objects
    int code;
public:
    Item() { code = ++count; }
    static void showCount() {  // only static members accessible
        cout << "Objects created: " << count << endl;
    }
};
int Item::count = 0;           // definition outside class

int main() {
    Item a, b, c;
    Item::showCount();         // Objects created: 3
}
```

