**Class-to-class conversion** is done either by a constructor in the destination class or by a conversion operator in the source class. Here the sum of all data members of class `A` is converted into an object of class `B` using a conversion operator in `A`. A friend function version is also given.

#### (a) Using conversion operator (class to class)

```cpp
#include <iostream>
using namespace std;

class B {
    int total;
public:
    B(int t = 0) : total(t) {}
    void show() { cout << "Sum of members of A stored in B = " << total << endl; }
};

class A {
    int x, y, z;
public:
    A(int a, int b, int c) : x(a), y(b), z(c) {}
    operator B() {                    // A -> B conversion
        return B(x + y + z);          // sum of all members
    }
};

int main() {
    A a(10, 20, 30);
    B b;
    b = a;                            // calls A::operator B()
    b.show();                         // 60
    return 0;
}
```

#### (b) Using a friend function

```cpp
#include <iostream>
using namespace std;

class A;                              // forward declaration

class B {
    int total;
public:
    B(int t = 0) : total(t) {}
    void show() { cout << "Sum = " << total << endl; }
    friend B sumOf(A a);
};

class A {
    int x, y, z;
public:
    A(int a, int b, int c) : x(a), y(b), z(c) {}
    friend B sumOf(A a);              // can access private members of A and B
};

B sumOf(A a) {
    B temp;
    temp.total = a.x + a.y + a.z;
    return temp;
}

int main() {
    A a(10, 20, 30);
    B b = sumOf(a);
    b.show();                         // Sum = 60
    return 0;
}
```

Output (both): sum = 60.

