Class `MATRIX` stores a square matrix (up to 10 x 10). Constructors: default (zero matrix) and parameterised (order n). Determinant is computed by recursive cofactor expansion; transpose by swapping rows and columns.

```cpp
#include <iostream>
using namespace std;

class MATRIX {
    int n;
    int a[10][10];
public:
    MATRIX() : n(0) {}                                   // default constructor
    MATRIX(int order) : n(order) {                       // parameterised constructor
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                a[i][j] = 0;
    }
    void read() {
        cout << "Enter " << n << "x" << n << " matrix:\n";
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                cin >> a[i][j];
    }
    void display() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) cout << a[i][j] << "\t";
            cout << endl;
        }
    }
    long determinant() { return det(a, n); }

    MATRIX transpose() {
        MATRIX t(n);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                t.a[j][i] = a[i][j];
        return t;
    }
private:
    long det(int m[10][10], int k) {
        if (k == 1) return m[0][0];
        if (k == 2) return m[0][0]*m[1][1] - m[0][1]*m[1][0];
        long d = 0;
        int sub[10][10];
        for (int c = 0; c < k; c++) {                    // expand along first row
            for (int i = 1; i < k; i++) {
                int col = 0;
                for (int j = 0; j < k; j++) {
                    if (j == c) continue;
                    sub[i-1][col++] = m[i][j];
                }
            }
            d += ((c % 2 == 0) ? 1 : -1) * m[0][c] * det(sub, k - 1);
        }
        return d;
    }
};

int main() {
    int n;
    cout << "Enter order of matrix: ";
    cin >> n;
    MATRIX m(n);
    m.read();
    cout << "Matrix:\n";
    m.display();
    cout << "Determinant = " << m.determinant() << endl;
    MATRIX t = m.transpose();
    cout << "Transpose:\n";
    t.display();
    return 0;
}
```

Sample output (n = 2, matrix `1 2 / 3 4`):
```
Determinant = -2
Transpose:
1   3
2   4
```

Class `Rational` stores numerator `x` and denominator `y` (kept in lowest terms using the GCD). Addition and subtraction use:

$$\frac{a}{b} \pm \frac{c}{d} = \frac{ad \pm bc}{bd}$$

```cpp
#include <iostream>
using namespace std;

class Rational {
    int x, y;                                   // x/y
    int gcd(int a, int b) { return b == 0 ? (a < 0 ? -a : a) : gcd(b, a % b); }
    void reduce() {
        int g = gcd(x, y);
        if (g != 0) { x /= g; y /= g; }
        if (y < 0) { x = -x; y = -y; }          // keep denominator positive
    }
public:
    Rational(int a = 0, int b = 1) : x(a), y(b) { reduce(); }
    Rational add(Rational r) { return Rational(x * r.y + r.x * y, y * r.y); }
    Rational sub(Rational r) { return Rational(x * r.y - r.x * y, y * r.y); }
    void show() { cout << x << "/" << y; }
};

int main() {
    int a, b, c, d;
    cout << "Enter first rational (x y): ";
    cin >> a >> b;
    cout << "Enter second rational (x y): ";
    cin >> c >> d;
    Rational r1(a, b), r2(c, d);

    cout << "Sum        = "; r1.add(r2).show(); cout << endl;
    cout << "Difference = "; r1.sub(r2).show(); cout << endl;
    return 0;
}
```

Sample output:
```
Enter first rational (x y): 1 2
Enter second rational (x y): 1 3
Sum        = 5/6
Difference = 1/6
```

Check: $\frac{1}{2}+\frac{1}{3} = \frac{3+2}{6} = \frac{5}{6}$ and $\frac{1}{2}-\frac{1}{3} = \frac{3-2}{6} = \frac{1}{6}$.
